INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w01','Code accumulates faster than understanding','User Need','A waypoint is a meaningful place in a project — a user need, a design decision, a risk, a code component, a test, an open question, or a todo. Waypoints make implicit knowledge explicit and navigable, for both humans and AI agents."','Described in the Triple Debt paper (cognitive debt + intent debt)',-114.586882222616,-59.5244370955107,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w02','New developers need guided onboarding into intent','User Need','A new developer joining a project built with AI assistance may find the code works but can''t understand why decisions were made. Onboarding relies on whoever wrote the code being available to explain it — and even they may have forgotten. Cognitive Tours addresses this by letting the team leave navigable trails of understanding behind as they build.','',-99.1272970068765,255.185895434162,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w04','Waypoints','Feature','A Waypoint is a meaningful place in a software project — a user need, a design decision, a risky area, a key component, a test, an open question, or a todo. Waypoints are the nodes of the understanding map.','',357.411776177261,13.631255748079,'app/lib/types.ts');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w06','Tours','Feature','A tour can represent any ordered narrative: onboarding, a prioritized backlog, a sprint, or a roadmap. It supports navigation across waypoints to tell the story.','Originated in TagSEA Routes (2006) and the Tours Eclipse plugin',205.061476888487,109.441797410516,'app/lib/types.ts');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w07','File Path links','Feature','Waypoints can optionally link to a file in the project. Clicking the path copies it to the clipboard. This connects intent artifacts to the code they describe — closing the loop between why and where.','Phase 3 will add file preview in the detail panel',521.200175699163,159.510079113133,'app/components/WaypointDetail.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w08','Use React Flow for graph visualization','ADR','Decision: use @xyflow/react for the graph canvas. Saves weeks of custom graph work. React Flow is TypeScript-first, mature, and handles node rendering, edge routing, drag-to-connect, and pan/zoom out of the box.','One limitation: edge deletion via keyboard is unreliable on Mac — requires a workaround.',673.933087459319,-22.7606285354655,'docs/adr/001-use-react-flow.md');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w09','Local state for MVP (now superseded)','ADR','Decision: Phase 1 used React useState with mock data only — no database. Rationale: validate the core concept before adding infrastructure. Now superseded by Phase 2 SQLite + Prisma persistence.','Status: Superseded by Phase 2',-398.160539269318,407.725786859398,'docs/adr/002-local-state-for-mvp.md');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w10','SQLite + Prisma for persistence','ADR','Decision: use SQLite via Prisma ORM for local persistence. Rationale: single-user app with no need for a server database. SQLite runs in-process, requires no setup, and Prisma provides type-safe queries and migrations.','Phase 2 implementation',360.017987342477,-463.906045064087,'prisma/schema.prisma');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w11','Optimistic updates for all mutations','ADR','Decision: all mutations update the UI immediately without waiting for database confirmation. On failure, the UI reverts and shows an error banner. Rationale: makes the graph feel responsive and natural for interactive use.','More details on The decision: Optimistic updates for all mutations
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w12','ShrimpApp — root state component','Code Component','The single "use client" root that owns all app state (waypoints, edges, tours, selection, active tour, load state, error message). All mutation handlers are defined here and passed as props. Keeps state management simple — no global stores.','',709.358671666668,-298.081710683679,'app/components/ShrimpApp.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w13','WaypointGraph — React Flow canvas','Code Component','The left-panel component that renders the understanding map as an interactive graph. Uses React Flow with a custom WaypointNode type for type-coloured nodes and drag-to-connect handles. Supports pan, zoom, node drag, edge delete.','',909.538428885153,-184.67357096438,'app/components/WaypointGraph.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w14','WaypointDetail — right panel','Code Component','The right-panel component showing the selected waypoint''s type badge, title, description, notes, and file path (with clipboard copy). Also surfaces Edit and Delete actions. Shows an empty-state prompt when nothing is selected.','',1286.23195836513,-87.088027752571,'app/components/WaypointDetail.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w15','TourBar — tour navigation','Code Component','The top-bar component with tour selector dropdown, Prev/Next/Finish buttons, step counter, and tour editor popup. The editor lets users create and edit tours by adding waypoints in order with up/down reordering.','',1140.15292544199,-369.739883260925,'app/components/TourBar.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w16','WaypointForm — create/edit form','Code Component','Modal form for creating and editing waypoints. Fields: label, type (8 options), description, notes, filePath. Opened from the graph "+ Add Waypoint" button or the detail panel Edit action.','',1291.17523476019,-202.281664281437,'app/components/WaypointForm.tsx');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w17','Core data types','Code Component','TypeScript interfaces for the entire app: WaypointType (union of 8 types), Waypoint, WaypointEdge, Tour, AppState. The single source of truth for what every entity is. All components and API routes import from here.','',420.425614718553,-313.264269094266,'app/lib/types.ts');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w18','Prisma schema','Code Component','Defines the SQLite database structure: Waypoint, Edge, Tour, TourWaypoint (join table with order column for preserving tour waypoint sequence). The source of truth for persistence.','',691.06156697982,-456.015460605832,'prisma/schema.prisma');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w19','db-mappers — Prisma to AppState translation','Code Component','The database stores waypoint positions as posX and posY columns. The app expects position as {x, y}. db-mappers translates between the two.','',964.731345668974,-469.744363559132,'app/lib/db-mappers.ts');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w20','Playwright tests — not yet written','Test','Acceptance tests to be written using Playwright: (1) persistence — create waypoint, refresh, verify present; (2) tour navigation — step through all waypoints, verify highlight; (3) delete cascade — delete waypoint, verify removed from graph, edges, and tours.','TODO: write before deploying to Vercel for real users',252.128208264067,707.011028215194,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w21','Manual tour navigation acceptance test','Test','Manual acceptance test: select "How Shrimp Works" tour, advance through all steps, verify each step highlights the correct graph node and shows the correct detail content, confirm the last step shows "Finish".','',499.99706835318,708.415110879108,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w22','Graph becomes too dense to navigate','Risk','As a project grows, the graph may become cluttered with dozens of overlapping nodes and crossing edges. Mitigation: keep projects to 10-30 waypoints for now. Filtering, search, and grouping are future features.','',148.907140914794,-120.600021452488,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w23','SQLite not suitable for cloud deployment','Risk','SQLite runs locally and resets on Vercel deployments (ephemeral filesystem). For cloud deployment, migrate to Turso (SQLite-compatible, hosted) or PostgreSQL. Not a concern for local single-user use.','Mitigation: use Turso when ready to deploy',49.7181558446847,-460.335982608023,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w24','Read the spec and constitution before writing components','AI Instruction','INSTRUCTION FOR AI AGENTS: Before writing any component or API route, read specs/001-shrimp-mvp/spec.md, plan.md, and the constitution at .specify/memory/constitution.md. Do not add props, state, or features not defined in the contracts. Follow Principle I (Simplicity) and Principle VIII (Human and Agent Readable).','',-408.33793149518,-103.531032340944,'.specify/memory/constitution.md');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w26','How should waypoints be exported and shared?','Open Question','When a project''s understanding map is ready to share, how does it leave Shrimp? Options: export to JSON, export to Markdown, publish as a read-only URL, push to GitHub wiki, or embed in a README. Not in scope for current phases.','',-7.03431944071993,702.827685774637,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w27','Should Cognitive Tours be a VS Code extension?','Open Question','Would Shrimp be more useful as a VS Code extension (embedded in the editor, direct file access) vs a standalone web app (tool-agnostic, shareable URL) vs a local CLI tool? Each changes the architecture significantly.','Current choice: web app for maximum accessibility',-233.838630808946,705.71963849543,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w28','How to show file contents in the detail panel?','Open Question','Phase 3 idea: add a "File" tab to the detail panel showing the contents of the linked file. Needs a server-side API route to read files safely. Should it show the full file or just relevant sections? How to handle large files?','Planned for Phase 4',-499.476553025417,743.210446246846,'');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w29','Mitigate and repair cognitive debt','Goal','The overarching purpose of Cognitive Tours — helping developers and teams construct and maintain shared understanding of software systems, so that cognitive and intent debt don''t accumulate and paralyze them.
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w-1780379099199','Filter waypoints by type (to reduce clutter)','Feature','A filter button on the top left of the graph that has a list and toggles for each waypoint type.  Hides nodes of the selected types and their connected edges.  Default all types are shown.  State is saved in ShrimpAPp and passed to WaypointGraph.
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w-1780409255110','Import Markdown Tours into Graph','Open Question','Could the skill output (markdown tour) be imported into the graph app to create clickable, navigable waypoints automatically? Would close the loop between the dialogue-based authoring approach and the visual navigation layer. Currently these are two separate workflows — import would make them complementary rather than parallel.','',721.127790582186,706.732127119039,'cognitive-tours-skill.md');
INSERT INTO Waypoint (id, label, type, description, notes, posX, posY, filePath) VALUES ('w-1780412091739','Deep link to function or symbol in VS Code','Open Question','Currently waypoints link to a file via vscode://file/path. Could extend this to link to a specific function or symbol using vscode://file/path/to/file.ts#FunctionName. More precise than file-level links but adds maintenance overhead as code changes. Line numbers go stale; symbol names are more stable. Is the added precision worth the maintenance cost?
